import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/common/Navbar';
import Footer from './components/common/Footer';
import HeroSection from './components/home/HeroSection';
import DestinationGrid from './components/home/DestinationGrid';
import CurationSection from './components/home/CurationSection';
import MegaboxGuide from './components/home/MegaboxGuide';
import Carousel3D from './components/Carousel3D';
import SchedulePage from './pages/SchedulePage';
import { getLatestMovies } from './api/tmdb';
import './App.css';

function Home({ movies, currentIndex, setCurrentIndex }) {
  const currentMovie = movies[currentIndex] || movies[0] || null;

  return (
    /* 💡 섹션별 스크롤 스냅 및 불규칙 그라데이션 컨테이너 */
    <div className="w-full flex flex-col">
      
      {/* 섹션 1: 히어로 영역 */}
      <section className="snap-section flex flex-col justify-center bg-gradient-to-br from-[#1b0c2e] via-[#0b090e] to-[#241038] relative overflow-hidden">
        <HeroSection currentMovie={currentMovie} />
      </section>

      {/* 섹션 2: 3D 캐러셀 영역 */}
      <section className="snap-section flex flex-col justify-center bg-gradient-to-tr from-[#0b090e] via-[#120f24] to-[#1e1035] relative overflow-hidden py-12">
        <Carousel3D movies={movies} currentIndex={currentIndex} setCurrentIndex={setCurrentIndex} />
      </section>

      {/* 섹션 3: 데스티네이션 그리드 영역 */}
      <section className="snap-section flex flex-col justify-center bg-gradient-to-bl from-[#0f0b1a] via-[#180e29] to-[#0b090e] relative overflow-hidden py-12">
        <DestinationGrid movies={movies} />
      </section>

      {/* 섹션 4: 큐레이션 영역 */}
      <section className="snap-section flex flex-col justify-center bg-gradient-to-tr from-[#200d38] via-[#351b63] to-[#0b090e] relative overflow-hidden py-12">
        <CurationSection />
      </section>

      {/* 섹션 5: 가이드 영역 */}
      <section className="snap-section flex flex-col justify-center bg-gradient-to-b from-[#0b090e] via-[#150a21] to-[#0b090e] relative overflow-hidden py-12">
        <MegaboxGuide />
      </section>

    </div>
  );
}

function App() {
  const [movies, setMovies] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const fetchMovies = async () => {
      const data = await getLatestMovies();
      if (data && data.length > 0) {
        setMovies(data);
      }
    };
    fetchMovies();
  }, []);

  return (
    <Router>
      <div className="bg-[#0b090e] min-h-screen text-white font-sans flex flex-col justify-between selection:bg-purple-500 selection:text-white">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route 
              path="/" 
              element={
                <Home 
                  movies={movies} 
                  currentIndex={currentIndex} 
                  setCurrentIndex={setCurrentIndex} 
                />
              } 
            />
            <Route path="/schedule" element={<SchedulePage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
